import{_ as i,C as r,o as l,c as s,j as d,a as e,E as o,a5 as a}from"./chunks/framework.BYIUCCsM.js";const f=JSON.parse('{"title":"引导","description":"","frontmatter":{},"headers":[],"relativePath":"components/tour.md","filePath":"components/tour.md","lastUpdated":1787598366000}'),h={name:"components/tour.md"},p={id:"引导",tabindex:"-1"};function u(g,t,b,x,m,T){const n=r("Badge"),c=r("XhDemo");return l(),s("div",null,[d("h1",p,[t[0]||(t[0]=e("引导 ",-1)),o(n,{type:"info",text:"tour"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#引导","aria-label":'Permalink to "引导 <Badge type="info" text="tour" />"'},"​",-1))]),t[3]||(t[3]=a('<p>一串聚光灯步骤，逐个指向界面上的元素并解释它。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>新功能上线、首次进入复杂界面时的一次性介绍。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>界面本身不好懂：改界面，别用引导补丁。</li><li>用户需要随时查阅的说明：写进帮助或<a href="./tooltip">文字提示</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>聚光灯把目标从遮罩里挖出来，<code>spotlightPadding</code> 决定挖多大。</li><li><code>autoScroll</code> 把目标滚进视野。</li><li>可以有居中的无目标步（开场与结束）。</li><li>步序与展开都可受控，另有完成与跳过两个回调。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>steps 是唯一事实源，组件只按下标取用；每步的 target 是一个 CSS 选择器，高亮框与浮层都锚在它上面</p>',10)),o(c,{src:"tour/01-basic"}),t[4]||(t[4]=d("h3",{id:"居中步",tabindex:"-1"},[e("居中步 "),d("a",{class:"header-anchor",href:"#居中步","aria-label":'Permalink to "居中步"'},"​")],-1)),t[5]||(t[5]=d("p",null,"不写 target 的那一步不锚定任何元素：浮层居中、不画高亮框、也不出箭头，适合当开场白与收尾",-1)),o(c,{src:"tour/02-centered"}),t[6]||(t[6]=d("h3",{id:"受控",tabindex:"-1"},[e("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[7]||(t[7]=d("p",null,"传了 open 与 step 就由宿主说了算：内部不再自改，只发意图，浮层里的按钮与外面的进度读的是同一份状态",-1)),o(c,{src:"tour/03-controlled"}),t[8]||(t[8]=a('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tour&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTourArrow</code> <code>XhTourBackdrop</code> <code>XhTourCloseTrigger</code> <code>XhTourContent</code> <code>XhTourDescription</code> <code>XhTourNextTrigger</code> <code>XhTourPositioner</code> <code>XhTourPrevTrigger</code> <code>XhTourProgressText</code> <code>XhTourRoot</code> <code>XhTourSkipTrigger</code> <code>XhTourSpotlight</code> <code>XhTourTitle</code></td></tr><tr><td>组合式函数</td><td><code>useTour</code></td></tr><tr><td>状态机</td><td><code>tourMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tour.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;tour&quot;</code>：<strong><code>root</code></strong> · <code>backdrop</code> · <code>spotlight</code> · <code>positioner</code> · <strong><code>content</code></strong> · <code>title</code> · <code>description</code> · <code>progress-text</code> · <code>prev-trigger</code> · <code>next-trigger</code> · <code>skip-trigger</code> · <code>close-trigger</code> · <code>arrow</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>steps</code></td><td><code>TourStep[]</code></td><td></td><td>步骤清单。它同时是步序的上界与读屏&quot;第 m 步，共 n 步&quot;的分母。</td></tr><tr><td><code>step</code></td><td><code>number</code></td><td></td><td>当前步序（0 起）。给定即受控：内部不再自改，只发 onStepChange。</td></tr><tr><td><code>defaultStep</code></td><td><code>number</code></td><td></td><td>非受控初值，默认 0。</td></tr><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>placement</code></td><td><code>Placement</code></td><td></td><td>整份引导的首选放置位，默认 bottom；单步可用自己的 placement 覆盖。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，缺省 ltr。只改写浮层在行内轴上 start 与 end 的落点。</td></tr><tr><td><code>offset</code></td><td><code>number</code></td><td></td><td>浮层与目标的间距（px）。</td></tr><tr><td><code>closeOnEscape</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>closeOnInteractOutside</code></td><td><code>boolean</code></td><td></td><td>层外交互关闭，默认 false：引导要退出得走 skip 或 close 这两个明确出口。</td></tr><tr><td><code>showBackdrop</code></td><td><code>boolean</code></td><td></td><td>画遮罩，默认 true。</td></tr><tr><td><code>spotlightPadding</code></td><td><code>number</code></td><td></td><td>高亮框在目标四周留出的空白（px），默认 8。</td></tr><tr><td><code>autoScroll</code></td><td><code>boolean</code></td><td></td><td>展开与换步时自动把目标滚进视口（nearest，已可见时不动），默认 true。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TourTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onStepChange</code></td><td><code>(details: TourStepChangeDetails) =&gt; void</code></td><td></td><td>步序变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: TourOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控时随内部转移一并通知。</td></tr><tr><td><code>onComplete</code></td><td><code>(details: TourCompleteDetails) =&gt; void</code></td><td></td><td>末步再按&quot;下一步&quot;：先发它，再按 onOpenChange 关闭。</td></tr><tr><td><code>onSkip</code></td><td><code>(details: TourSkipDetails) =&gt; void</code></td><td></td><td>用户主动放弃（skip-trigger 或 Escape）：先发它，再按 onOpenChange 关闭。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>TourOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr><tr><td><code>step-change</code></td><td><code>TourStepChangeDetails</code></td><td>步序变化；detail 为 <code>{ step: number }</code></td></tr><tr><td><code>complete</code></td><td><code>TourCompleteDetails</code></td><td>末步再按下一步；detail 为 <code>{ step: number }</code></td></tr><tr><td><code>skip</code></td><td><code>TourSkipDetails</code></td><td>用户放弃（跳过按钮或 Escape）；detail 为 <code>{ step: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTourRoot</code></td><td><code>default</code></td><td><code>TourRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>backdrop</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>spotlight</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>prev-trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>next-trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>skip-trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>CLOSE</code> · <code>STEP.SET</code> · <code>STEP.PREV</code> · <code>STEP.NEXT</code> · <code>SKIP</code> · <code>GEOMETRY.SYNC</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code> · <code>isLastStep</code> · <code>isLastStepOpenControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useTour</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>step</code></td><td><code>number</code></td><td>当前步序，恒在 [0, count - 1] 内；清单为空时为 0。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td></tr><tr><td><code>currentStep</code></td><td><code>TourStep | null</code></td><td>当前步的声明；清单为空时为 null。</td></tr><tr><td><code>firstStep</code></td><td><code>boolean</code></td><td>停在首步：上一步按钮据此禁用。</td></tr><tr><td><code>lastStep</code></td><td><code>boolean</code></td><td>停在末步：下一步按钮据此改文案（&quot;完成&quot;）。</td></tr><tr><td><code>anchored</code></td><td><code>boolean</code></td><td>这一步锚定了页面元素：居中步为 false，此时不画高亮框也不出箭头。</td></tr><tr><td><code>progressText</code></td><td><code>string</code></td><td>&quot;第 m 步，共 n 步&quot;。作者没写 progress-text 的内容时由适配器填上。</td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>setStep</code></td><td><code>(next: number) =&gt; void</code></td><td>直接跳到某一步；越界会被夹回 [0, count - 1]。</td></tr><tr><td><code>goToNextStep</code></td><td><code>() =&gt; void</code></td><td>末步再走一步 = 完成：先发 onComplete，再关闭。</td></tr><tr><td><code>goToPrevStep</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>skip</code></td><td><code>() =&gt; void</code></td><td>放弃引导：先发 onSkip，再关闭。</td></tr><tr><td><code>remeasure</code></td><td><code>() =&gt; void</code></td><td>重量高亮框与浮层位置：目标节点被外部改动（换位、变尺寸）后调它校准。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBackdropProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSpotlightProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPositionerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getProgressTextProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPrevTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getNextTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getSkipTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCloseTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getArrowProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/dialog-modal/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code> / <code>Space</code></td><td>open 且焦点在 content 上（不在按钮等控件上）</td><td>走到下一步；停在末步时完成引导并关闭</td></tr><tr><td><code>Escape</code></td><td>open 且 closeOnEscape</td><td>放弃引导（发 onSkip）并关闭</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowDown</code> / <code>ArrowLeft</code> / <code>ArrowRight</code></td><td>open</td><td>一概不接管：既不换步也不阻止默认行为，留给页面滚动与读屏浏览</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>open</td><td>焦点陷在 content 内循环，跑出去会被拉回来</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>backdrop</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>spotlight</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-describedby</code></td><td><code>description</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>title</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-modal</code></td><td>&#39;true&#39;</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;dialog&#39;</td></tr><tr><td><code>progress-text</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>close-trigger</code></td><td><code>aria-label</code></td><td>translations?.close</td></tr><tr><td><code>arrow</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/tour.css</code> 按部件选择：<code>[data-scope=&quot;tour&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 与 <code>xihan.motion</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-step</code></td><td>String(step)</td></tr><tr><td><code>backdrop</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>spotlight</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>positioner</code></td><td><code>data-position</code></td><td>&#39;anchored&#39; | &#39;center&#39;</td></tr><tr><td><code>positioner</code></td><td><code>data-positioned</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>positioner</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-step</code></td><td>String(step)</td></tr><tr><td><code>progress-text</code></td><td><code>data-step</code></td><td>String(step)</td></tr><tr><td><code>prev-trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>next-trigger</code></td><td><code>data-last</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>next-trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>skip-trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>arrow</code></td><td><code>data-placement</code></td><td>定位引擎算出的实际落位</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-tour-action-radius</code> · <code>--xh-tour-arrow-size</code> · <code>--xh-tour-backdrop-bg</code> · <code>--xh-tour-backdrop-layer</code> · <code>--xh-tour-bg</code> · <code>--xh-tour-border</code> · <code>--xh-tour-close-bg-active</code> · <code>--xh-tour-close-bg-hover</code> · <code>--xh-tour-close-radius</code> · <code>--xh-tour-close-size</code> · <code>--xh-tour-description-fg</code> · <code>--xh-tour-fg</code> · <code>--xh-tour-gap</code> · <code>--xh-tour-icon-size</code> · <code>--xh-tour-max-h</code> · <code>--xh-tour-max-w</code> · <code>--xh-tour-next-bg</code> · <code>--xh-tour-next-bg-hover</code> · <code>--xh-tour-next-fg</code> · <code>--xh-tour-positioner-layer</code> · <code>--xh-tour-positioner-padding</code> · <code>--xh-tour-progress-fg</code> · <code>--xh-tour-progress-font-size</code> · <code>--xh-tour-px</code> · <code>--xh-tour-py</code> · <code>--xh-tour-radius</code> · <code>--xh-tour-shadow</code> · <code>--xh-tour-skip-trigger-px</code> · <code>--xh-tour-spotlight-layer</code> · <code>--xh-tour-spotlight-radius</code> · <code>--xh-tour-spotlight-ring</code> · <code>--xh-tour-spotlight-shroud</code> · <code>--xh-tour-title-fg</code> · <code>--xh-tour-title-font-size</code> · <code>--xh-tour-title-font-weight</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>关键帧 <code>xh-fade-in</code> · <code>xh-fade-out</code> · <code>xh-pop-in</code> · <code>xh-pop-out</code> · <code>xh-tour-spotlight-in</code> · <code>xh-tour-spotlight-out</code> 随皮肤自带，不引用别处文件里的名字；状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./dialog">对话框</a>配合做开场；结束后引导用户去<a href="./result">结果页</a>或具体功能。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>步数压到三到五步，多了没人走完。</li><li>跳过入口从第一步就要有，且要显眼。</li><li>只讲一次，记住用户已经看过。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>强制走完不许跳过。</li><li>引导目标在当前视口里不存在（还没渲染出来），聚光灯挖了个空。</li></ul>',48))])}const q=i(h,[["render",u]]);export{f as __pageData,q as default};
